export function applyVerifiedCatalogFacts(plans: Plan[]): Plan[] {
  return plans.map(plan => {
    const facts = verifiedCatalogFacts.filter(fact => fact.id === plan.id);
    if (!facts.length) return plan;
    const coverageCells = { ...plan.coverageCells };
    const sources = [...plan.sources];
    for (const fact of facts) {
      if (!(fact.field in coverageCells)) throw new Error(`Unknown catalog field: ${plan.id}:${fact.field}`);
      coverageCells[fact.field] = fact.cell;
      const index = sources.findIndex(source => source.id === fact.source.id);
      if (index < 0) sources.push(fact.source); else sources[index] = fact.source;
    }
    return { ...plan, coverageCells, sources, coverage: Object.fromEntries(Object.entries(coverageCells).map(([key, cell]) => [key, cell.value])) };
  });
}
